package com.trampolim.api.trust;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.scheduling.annotation.Scheduled;import com.trampolim.api.radar.RadarBridge;
@Configuration public class ReportGatewayConfig {
 @Bean("candidateListingReports")ListingReportGateway candidates(@Qualifier("jdbcTemplate")JdbcTemplate db,@Qualifier("oportunidadesTransactionManager")PlatformTransactionManager manager,RadarBridge bridge){return new ListingReportGateway(db,manager,bridge,false);}
 @Bean("studentListingReports")@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")ListingReportGateway students(@Qualifier("capacitaJdbcTemplate")JdbcTemplate db,@Qualifier("capacitaTransactionManager")PlatformTransactionManager manager,RadarBridge bridge){return new ListingReportGateway(db,manager,bridge,true);}
 @Bean ReportDelivery delivery(@Qualifier("candidateListingReports")ListingReportGateway candidate,@Qualifier("studentListingReports")ObjectProvider<ListingReportGateway> student){return new ReportDelivery(candidate,student);}
 public static class ReportDelivery {private final ListingReportGateway candidate;private final ObjectProvider<ListingReportGateway> student;@Value("${trust.report-delivery-enabled:${operations.catalog-jobs-enabled:true}}")private boolean enabled;ReportDelivery(ListingReportGateway candidate,ObjectProvider<ListingReportGateway> student){this.candidate=candidate;this.student=student;}@Scheduled(initialDelayString="30000",fixedDelayString="30000")public void pump(){if(enabled){candidate.pump();student.ifAvailable(ListingReportGateway::pump);}}}
}
